solutions = {'A01': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n = int(lines[0])\n    arr = lines[1].split()\n    x, p = lines[2].split()\n    arr.insert(int(p), x)\n    return ' '.join(arr)\nprint(solve(sys.stdin.read()))", 'A02': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    s = list(set(arr))\n    if len(s) < 2: return "NONE"\n    s.sort()\n    return str(s[-2])\nprint(solve(sys.stdin.read()))', 'A03': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n = int(lines[0])\n    arr = lines[1].split()\n    k = int(lines[2]) % n\n    if k == 0: return ' '.join(arr)\n    return ' '.join(arr[-k:] + arr[:-k])\nprint(solve(sys.stdin.read()))", 'A04': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    return str(best)\nprint(solve(sys.stdin.read()))", 'A05': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n = int(lines[0])\n    arr = list(map(int, lines[1].split()))\n    ans = [1]*n\n    p = 1\n    for i in range(n):\n        ans[i] = p\n        p *= arr[i]\n    p = 1\n    for i in range(n-1, -1, -1):\n        ans[i] *= p\n        p *= arr[i]\n    return ' '.join(map(str, ans))\nprint(solve(sys.stdin.read()))", 'S01': 'import sys\ndef solve(data):\n    s = data.strip().lower()\n    return "YES" if s == s[::-1] else "NO"\nprint(solve(sys.stdin.read()))', 'S02': 'import sys\nfrom collections import Counter\ndef solve(data):\n    s = data.strip()\n    c = Counter(s)\n    for ch in s:\n        if c[ch] == 1: return ch\n    return "NONE"\nprint(solve(sys.stdin.read()))', 'S03': "import sys\ndef solve(data):\n    return ' '.join(data.strip().split()[::-1])\nprint(solve(sys.stdin.read()))", 'S04': 'import sys\ndef solve(data):\n    s = data.strip()\n    last = {}\n    ans = 0\n    start = 0\n    for i, c in enumerate(s):\n        if c in last and last[c] >= start:\n            start = last[c] + 1\n        last[c] = i\n        ans = max(ans, i - start + 1)\n    return str(ans)\nprint(solve(sys.stdin.read()))', 'S05': 'import sys\nfrom collections import Counter\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    if len(lines) < 2: return "NONE"\n    s, p = lines[0], lines[1]\n    need = Counter(p)\n    missing = len(p)\n    left = 0\n    best_len = float(\'inf\')\n    best_start = 0\n    for right, c in enumerate(s):\n        if need[c] > 0: missing -= 1\n        need[c] -= 1\n        while missing == 0:\n            if right - left + 1 < best_len:\n                best_len = right - left + 1\n                best_start = left\n            need[s[left]] += 1\n            if need[s[left]] > 0: missing += 1\n            left += 1\n    return s[best_start:best_start+best_len] if best_len != float(\'inf\') else "NONE"\nprint(solve(sys.stdin.read()))', 'SE01': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = lines[1].split()\n    t = lines[2]\n    try: return str(arr.index(t))\n    except: return "-1"\nprint(solve(sys.stdin.read()))', 'SE02': 'import sys\nimport bisect\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    t = int(lines[2])\n    idx = bisect.bisect_left(arr, t)\n    return str(idx) if idx < len(arr) and arr[idx] == t else "-1"\nprint(solve(sys.stdin.read()))', 'SE03': 'import sys\nimport bisect\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    t = int(lines[2])\n    l = bisect.bisect_left(arr, t)\n    if l == len(arr) or arr[l] != t: return "-1 -1"\n    r = bisect.bisect_right(arr, t) - 1\n    return f"{l} {r}"\nprint(solve(sys.stdin.read()))', 'SE04': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    t = int(lines[2])\n    l, r = 0, len(arr)-1\n    while l <= r:\n        m = (l+r)//2\n        if arr[m] == t: return str(m)\n        if arr[l] <= arr[m]:\n            if arr[l] <= t < arr[m]: r = m - 1\n            else: l = m + 1\n        else:\n            if arr[m] < t <= arr[r]: l = m + 1\n            else: r = m - 1\n    return "-1"\nprint(solve(sys.stdin.read()))', 'SE05': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    l, r = 0, len(arr)-1\n    while l < r:\n        m = (l+r)//2\n        if arr[m] > arr[m+1]: r = m\n        else: l = m + 1\n    return str(l)\nprint(solve(sys.stdin.read()))", 'SO01': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    return ' '.join(map(str, sorted(arr)))\nprint(solve(sys.stdin.read()))", 'SO02': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n = int(lines[0])\n    arr1 = list(map(int, lines[1].split())) if n > 0 else []\n    m = int(lines[2])\n    arr2 = list(map(int, lines[3].split())) if m > 0 else []\n    return ' '.join(map(str, sorted(arr1 + arr2)))\nprint(solve(sys.stdin.read()))", 'SO03': "import sys\nfrom collections import Counter\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    c = Counter(arr)\n    arr.sort(key=lambda x: (-c[x], x))\n    return ' '.join(map(str, arr))\nprint(solve(sys.stdin.read()))", 'SO04': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    def mergesort(a):\n        if len(a) <= 1: return a, 0\n        mid = len(a)//2\n        left, inv1 = mergesort(a[:mid])\n        right, inv2 = mergesort(a[mid:])\n        inv = inv1 + inv2\n        merged = []\n        i = j = 0\n        while i < len(left) and j < len(right):\n            if left[i] <= right[j]:\n                merged.append(left[i]); i+=1\n            else:\n                merged.append(right[j]); j+=1\n                inv += len(left) - i\n        merged.extend(left[i:])\n        merged.extend(right[j:])\n        return merged, inv\n    return str(mergesort(arr)[1])\nprint(solve(sys.stdin.read()))", 'SO05': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    sarr = sorted(list(enumerate(arr)), key=lambda x: x[1])\n    vis = {i: False for i in range(len(arr))}\n    ans = 0\n    for i in range(len(arr)):\n        if vis[i] or sarr[i][0] == i:\n            continue\n        cycle = 0\n        j = i\n        while not vis[j]:\n            vis[j] = True\n            j = sarr[j][0]\n            cycle += 1\n        if cycle > 1: ans += cycle - 1\n    return str(ans)\nprint(solve(sys.stdin.read()))", 'A06': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    n = int(lines[0])\n    arr = list(map(int, lines[1].split()))\n    t = int(lines[2])\n    seen = set()\n    for x in arr:\n        if t - x in seen:\n            return "YES"\n        seen.add(x)\n    return "NO"\nprint(solve(sys.stdin.read()))', 'A07': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n, k = map(int, lines[0].split())\n    arr = list(map(int, lines[1].split()))\n    cur = sum(arr[:k])\n    best = cur\n    for i in range(k, len(arr)):\n        cur += arr[i] - arr[i-k]\n        best = max(best, cur)\n    return str(best)\nprint(solve(sys.stdin.read()))", 'A08': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    if not arr: return "0"\n    l, r = 0, len(arr) - 1\n    l_max, r_max = arr[l], arr[r]\n    ans = 0\n    while l < r:\n        if l_max < r_max:\n            l += 1\n            l_max = max(l_max, arr[l])\n            ans += l_max - arr[l]\n        else:\n            r -= 1\n            r_max = max(r_max, arr[r])\n            ans += r_max - arr[r]\n    return str(ans)\nprint(solve(sys.stdin.read()))', 'S06': 'import sys\nfrom collections import Counter\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    s = lines[0] if len(lines) > 0 else ""\n    t = lines[1] if len(lines) > 1 else ""\n    return "YES" if Counter(s) == Counter(t) else "NO"\nprint(solve(sys.stdin.read()))', 'S07': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    if len(lines) < 2: return ""\n    strs = lines[1:]\n    if not strs: return ""\n    s1 = min(strs)\n    s2 = max(strs)\n    for i, c in enumerate(s1):\n        if c != s2[i]:\n            return s1[:i]\n    return s1\nprint(solve(sys.stdin.read()))', 'S08': 'import sys\nfrom collections import defaultdict\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    if len(lines) < 2: return ""\n    strs = lines[1:]\n    d = defaultdict(list)\n    for s in strs:\n        d["".join(sorted(s))].append(s)\n    res = []\n    for k in d:\n        d[k].sort()\n        res.append(d[k])\n    res.sort(key=lambda x: x[0])\n    return "\\n".join(" ".join(g) for g in res)\nprint(solve(sys.stdin.read()))', 'SE06': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n = int(lines[0])\n    b = int(lines[1])\n    def isBadVersion(v): return v >= b\n    l, r = 1, n\n    ans = -1\n    while l <= r:\n        m = (l+r)//2\n        if isBadVersion(m):\n            ans = m\n            r = m - 1\n        else:\n            l = m + 1\n    return str(ans)\nprint(solve(sys.stdin.read()))", 'SE07': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    arr = list(map(int, lines[1].split()))\n    l, r = 0, len(arr)-1\n    while l < r:\n        m = (l+r)//2\n        if arr[m] > arr[r]: l = m + 1\n        else: r = m\n    return str(arr[l])\nprint(solve(sys.stdin.read()))", 'SE08': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    n, m = map(int, lines[0].split())\n    arr1 = list(map(int, lines[1].split())) if n > 0 else []\n    arr2 = list(map(int, lines[2].split())) if m > 0 else []\n    arr = sorted(arr1 + arr2)\n    tot = len(arr)\n    if tot == 0: return "0.0"\n    if tot % 2 == 1:\n        ans = float(arr[tot//2])\n    else:\n        ans = (arr[tot//2 - 1] + arr[tot//2]) / 2.0\n    return f"{ans:.1f}"\nprint(solve(sys.stdin.read()))', 'SO06': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    n = int(lines[0])\n    intervals = []\n    for i in range(1, n+1):\n        intervals.append(list(map(int, lines[i].split())))\n    if not intervals: return ""\n    intervals.sort(key=lambda x: x[0])\n    ans = [intervals[0]]\n    for i in range(1, len(intervals)):\n        if intervals[i][0] <= ans[-1][1]:\n            ans[-1][1] = max(ans[-1][1], intervals[i][1])\n        else:\n            ans.append(intervals[i])\n    return "\\n".join(f"{x[0]} {x[1]}" for x in ans)\nprint(solve(sys.stdin.read()))', 'SO07': "import sys\ndef solve(data):\n    lines = data.strip().split('\\n')\n    n, k = map(int, lines[0].split())\n    arr = list(map(int, lines[1].split()))\n    arr.sort(reverse=True)\n    return str(arr[k-1])\nprint(solve(sys.stdin.read()))", 'SO08': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    arr.sort()\n    return " ".join(map(str, arr))\nprint(solve(sys.stdin.read()))', 'SO09': 'import sys\ndef solve(data):\n    lines = data.strip().split(\'\\n\')\n    arr = list(map(int, lines[1].split()))\n    import bisect\n    sorted_list = []\n    ans = []\n    for x in reversed(arr):\n        idx = bisect.bisect_left(sorted_list, x)\n        ans.append(idx)\n        sorted_list.insert(idx, x)\n    ans.reverse()\n    return " ".join(map(str, ans))\nprint(solve(sys.stdin.read()))'}